namespace PipelineBenchmark;

/// <summary>
/// Represents raw sensor telemetry generated by the infinite data source.
/// </summary>
/// <param name="SequenceId">Monotonically increasing sequence number.</param>
/// <param name="DeviceId">Unique device identifier.</param>
/// <param name="Temperature">Measured ambient temperature in Celsius.</param>
/// <param name="Humidity">Measured relative humidity percentage.</param>
/// <param name="Timestamp">UTC generation timestamp.</param>
/// <param name="Payload">Simulated binary sensor payload for memory tracking.</param>
public record SensorMessage(
    long SequenceId,
    string DeviceId,
    double Temperature,
    double Humidity,
    DateTime Timestamp,
    byte[] Payload
);

/// <summary>
/// Represents telemetry enriched with computed meteorological indices and alert status.
/// </summary>
/// <param name="SequenceId">Original sequence identifier.</param>
/// <param name="DeviceId">Unique device identifier.</param>
/// <param name="Temperature">Measured ambient temperature in Celsius.</param>
/// <param name="Humidity">Measured relative humidity percentage.</param>
/// <param name="HeatIndex">Calculated apparent temperature / heat index.</param>
/// <param name="IsAlert">Indicates whether readings exceed threshold limits.</param>
/// <param name="EnrichedAt">UTC enrichment timestamp.</param>
/// <param name="Payload">Carried sensor payload.</param>
public record EnrichedMessage(
    long SequenceId,
    string DeviceId,
    double Temperature,
    double Humidity,
    double HeatIndex,
    bool IsAlert,
    DateTime EnrichedAt,
    byte[] Payload
);

/// <summary>
/// Represents an aggregated batch summary produced by the terminal sink.
/// </summary>
/// <param name="BatchNumber">Batch counter identifier.</param>
/// <param name="ItemCount">Number of records in this batch.</param>
/// <param name="AlertCount">Number of threshold alerts in this batch.</param>
/// <param name="AverageTemperature">Average temperature across batch items.</param>
/// <param name="ProcessedAt">UTC processing completion timestamp.</param>
public record ProcessedBatchResult(
    long BatchNumber,
    int ItemCount,
    int AlertCount,
    double AverageTemperature,
    DateTime ProcessedAt
);
